      "business": "Pinecone"
    },
    {
      "why": "Same enterprise-AI pattern of warm, light-infused hero, cream/dark alternating sections, and pill-shaped minimal controls — the warm-light-intelligence visual vocabulary is shared",
      "business": "Harvey (legal AI)"
    },
